  bucket = "terraveritas-deceptive-s3-bucket"
}

resource "aws_s3_bucket_public_access_block" "data" {
  bucket = aws_s3_bucket.data.id

  block_public_acls       = true
  block_public_policy     = true
  ignore_public_acls      = true
  restrict_public_buckets = true
}

resource "aws_s3_bucket_policy" "data" {
  bucket = aws_s3_bucket.data.id
  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Sid    = "RestrictedRead"
        Effect = "Allow"
        Principal = {
          AWS = "arn:aws:iam::123456789012:role/authorized-reader-role"
        }
        Action   = "s3:GetObject"
        Resource = "arn:aws:s3:::terraveritas-deceptive-s3-bucket/*"
      }
    ]
  })

  depends_on = [aws_s3_bucket_public_access_block.data]
}
```

Explanation: CKV_AWS_70 fails because the policy grants access to `Principal = "*"` (anyone, unauthenticated), which makes the bucket publicly readable via its policy. The fix replaces the wildcard principal with a specific, scoped principal (e.g., a specific IAM role/account ARN -- replace `arn:aws:iam::123456789012:role/authorized-reader-role` with whatever principal should legitimately have access in your environment). I also added an `aws_s3_bucket_public_access_block` resource as defense-in-depth so that even a misconfigured future policy can't accidentally expose the bucket publicly, and made the policy `depends_on` it to ensure ordering. If the bucket genuinely needs to be public (e.g., static website hosting), CKV_AWS_70 should instead be addressed by explicitly justifying and suppressing the check, not by leaving `Principal = "*"` unexamined.
